/**
 * src/routes/tours.js
 * Headless Publishing Pipeline — Cloudflare R2 backed.
 *
 * R2 bucket layout  (binding: env.TOUR_PAGES)
 * ─────────────────────────────────────────────────────────────────────────────
 *   templates/{template_id}.html       ← HTML templates (uploaded via API)
 *   {tenant_id}/{tour_slug}.html       ← published tour pages
 *
 * Placeholder convention  (UPPER_SNAKE_CASE, case-sensitive)
 * ─────────────────────────────────────────────────────────────────────────────
 *   {{TOUR_NAME}}   content_data.tour_name  || tours.title
 *   {{TOUR_CODE}}   content_data.tour_code
 *   {{ITINERARY}}   rendered <ol> from content_data.itinerary[]
 *   {{BASE_PRICE}}  content_data.base_price (raw number, format in template)
 *   {{DURATION}}    tours.duration_text || content_data.duration
 *   {{HIGHLIGHTS}}  rendered <ul> from content_data.highlights[]
 *   {{INCLUDES}}    rendered <ul> from content_data.includes[]
 *   {{EXCLUDES}}    rendered <ul> from content_data.excludes[]
 *   {{TOUR_SLUG}}   tours.slug
 *   {{TENANT_ID}}   tours.tenant_id
 *   {{LANG}}        tours.lang
 *
 * content_data shape (stored as JSON TEXT in D1)
 * ─────────────────────────────────────────────────────────────────────────────
 * {
 *   "tour_name":  "Hà Nội – Hạ Long 3N2Đ",
 *   "tour_code":  "HNX-HAL-3N2D",
 *   "base_price": 2500000,
 *   "itinerary":  [{ "day": 1, "title": "...", "description": "..." }],
 *   "highlights": ["Cave cruise", "Sunset views"],
 *   "includes":   ["Hotel", "Breakfast"],
 *   "excludes":   ["International flights"]
 * }
 */

import { Hono } from 'hono';
import { nanoid } from 'nanoid';
import { syncUniversalTourPage } from '../lib/universalSiteSync.js';
import {
  checkPublishPermission,
  buildPayButton,
  buildPreviewBanner,
  buildPreviewPayButton,
  buildPlatformBrand,
} from '../lib/publishGuard.js';

const tours = new Hono();

function scheduleUniversalTourSync(c, tenantId, tourId) {
  c.executionCtx.waitUntil(
    syncUniversalTourPage(c.env, tenantId, tourId)
      .then((result) => {
        if (!result?.ok) {
          console.warn(`[UNIVERSAL_SYNC_WARN] tenant=${tenantId} tour=${tourId} status=${result?.status} error=${result?.error}`);
        }
      })
      .catch((error) => {
        console.warn(`[UNIVERSAL_SYNC_ERROR] tenant=${tenantId} tour=${tourId}`, error?.message || error);
      })
  );
}

// ── Pure helpers ──────────────────────────────────────────────────────────────

/**
 * Convert a display title to a URL-safe slug.
 * Handles Vietnamese ä diacritics and the special 'đ' character.
 */
function slugify(text) {
  return String(text)
    .toLowerCase()
    .replace(/đ/g, 'd')                   // must precede NFD — no decomposition for đ
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')      // strip combining diacritics (à→a, etc.)
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 100);
}

/**
 * Sanitize a user-supplied identifier to be safe as an R2 key segment.
 * Allows only a–z, A–Z, 0–9, _ and -.
 */
function safeId(id) {
  return String(id ?? '').replace(/[^a-z0-9_-]/gi, '').slice(0, 80);
}

function renderList(items) {
  if (!Array.isArray(items) || items.length === 0) return '';
  return `<ul>\n${items.map(i => `  <li>${i}</li>`).join('\n')}\n</ul>`;
}

function renderItinerary(itinerary) {
  if (!Array.isArray(itinerary) || itinerary.length === 0) return '';
  return `<ol class="itinerary">\n${
    itinerary.map(item =>
      `  <li class="itinerary-day">\n` +
      `    <strong>Day ${item.day ?? ''}: ${item.title ?? ''}</strong>\n` +
      `    <p>${item.description ?? ''}</p>\n` +
      `  </li>`
    ).join('\n')
  }\n</ol>`;
}

/**
 * Replace all {{UPPER_SNAKE_KEY}} placeholders in an HTML template string.
 * Unknown placeholders are left as-is (transparent — safe for future extensions).
 */
function applyPlaceholders(html, vars) {
  return html.replace(/\{\{([A-Z0-9_]+)\}\}/g, (match, key) =>
    Object.prototype.hasOwnProperty.call(vars, key) ? String(vars[key] ?? '') : match
  );
}

// ── HTML escape (SEC: user-supplied strings injected via HTMLRewriter) ─────────
function escHtml(str) {
  return String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// ─────────────────────────────────────────────────────────────────────────────
// renderAndSaveDraftPage
// ─────────────────────────────────────────────────────────────────────────────
/**
 * Reads the sandbox detail template (`sandbox/{tenantId}/detail.html`) from
 * TOUR_PAGES R2, applies an HTMLRewriter pipeline to inject tour metadata, and
 * saves the result as a draft static page at
 * `sandbox/{tenantId}/tours/{slug}.html`.
 *
 * The draft page is clearly marked with a fixed amber ribbon and carries a
 * `<script type="application/json" id="__tour__">` data-island so inject.js
 * and the booking widget can consume the tour data client-side.
 *
 * Non-fatal by design: if the sandbox has not been initialised (no detail.html)
 * the function returns { ok: false, reason } without throwing, allowing tour
 * creation to succeed regardless.
 *
 * HTMLRewriter targets (generic selectors that work for any HTML template):
 *   <title>                    → "{tourName} (Draft)"
 *   <meta name="description">  → tour description (setAttribute)
 *   <meta property="og:title"> → tour name (setAttribute)
 *   first <article h2>         → tour name (setInnerContent)
 *   first <article p>          → tour description (setInnerContent)
 *   <body>                     → prepend draft ribbon, append data island
 *
 * @param {object} env       - Worker env bindings (needs TOUR_PAGES)
 * @param {string} tenantId  - Tenant primary key
 * @param {object} tour      - { id, slug, title, content_data (string|null) }
 * @returns {Promise<{ok: true, r2_key: string} | {ok: false, reason: string}>}
 */
async function renderAndSaveDraftPage(env, tenantId, tour) {
  if (!env.TOUR_PAGES) return { ok: false, reason: 'TOUR_PAGES binding not configured' };

  const templateKey = `sandbox/${tenantId}/detail.html`;
  const tmplObj     = await env.TOUR_PAGES.get(templateKey);
  if (!tmplObj) {
    return {
      ok:     false,
      reason: `Sandbox template not found at "${templateKey}". Run initializeTenantSandbox first.`,
    };
  }

  // Parse content_data — graceful fallback to empty object on missing/malformed JSON.
  let content = {};
  try {
    if (tour.content_data) {
      content = typeof tour.content_data === 'string'
        ? JSON.parse(tour.content_data)
        : tour.content_data;
    }
  } catch { /* keep empty content */ }

  const tourName  = escHtml(content.tour_name ?? tour.title ?? '');
  const tourDesc  = escHtml(content.hero_desc ?? content.description ?? content.tour_desc ?? '');
  const tourPrice = content.base_price != null ? String(content.base_price) : '';

  // ── Draft ribbon — fixed, amber, visible without JS ─────────────────────
  // Inlined styles so the ribbon works even when assets/css fails to load.
  const DRAFT_RIBBON =
    `<div id="__draft-ribbon__" style="position:fixed;top:0;left:0;right:0;z-index:9999;` +
    `background:#f59e0b;color:#1c1917;font:700 13px/36px system-ui,sans-serif;` +
    `text-align:center;letter-spacing:.05em;">` +
    `&#9679; DRAFT &#8212; Not published yet` +
    `</div>` +
    // Push page content down so ribbon doesn't overlap the header.
    `<style>body{padding-top:36px!important}</style>`;

  // ── JSON data island ─────────────────────────────────────────────────────
  // Consumed by inject.js and the booking widget client-side.
  // [SEC] JSON.stringify is used — no manual concatenation of user values.
  const DATA_ISLAND =
    `<script type="application/json" id="__tour__">` +
    JSON.stringify({
      id:         tour.id,
      slug:       tour.slug,
      title:      tour.title,
      status:     'draft',
      base_price: content.base_price ?? null,
      tour_code:  content.tour_code  ?? null,
      duration:   tour.duration_text ?? content.duration ?? null,
    }) +
    `</script>`;

  // ── HTMLRewriter pipeline ─────────────────────────────────────────────────
  // Closure flags: HTMLRewriter fires the handler for EVERY matching element;
  // flags gate injection to first-match-only where appropriate.
  let firstArticleH2Done = false;
  let firstArticlePDone  = false;

  const rewriter = new HTMLRewriter()

    // Page title
    .on('title', {
      element(el) {
        el.setInnerContent(tourName ? `${tourName} (Draft)` : 'Tour Draft');
      },
    })

    // SEO / social meta — setInnerContent not applicable; use setAttribute.
    .on('meta[name="description"]', {
      element(el) {
        if (tourDesc) el.setAttribute('content', tourDesc);
      },
    })
    .on('meta[property="og:title"]', {
      element(el) {
        if (tourName) el.setAttribute('content', tourName);
      },
    })
    .on('meta[property="og:description"]', {
      element(el) {
        if (tourDesc) el.setAttribute('content', tourDesc);
      },
    })

    // Primary content heading inside <article> — first match only.
    .on('article h2', {
      element(el) {
        if (!firstArticleH2Done && tourName) {
          firstArticleH2Done = true;
          el.setInnerContent(tourName);
        }
      },
    })

    // First descriptive paragraph inside <article>.
    .on('article p', {
      element(el) {
        if (!firstArticlePDone && tourDesc) {
          firstArticlePDone = true;
          el.setInnerContent(tourDesc);
        }
      },
    })

    // <body>: prepend draft ribbon + append data island.
    .on('body', {
      element(el) {
        el.prepend(DRAFT_RIBBON, { html: true });
        el.append(DATA_ISLAND,   { html: true });
      },
    });

  // Stream-transform the template response.
  const transformed = rewriter.transform(
    new Response(tmplObj.body, { headers: { 'Content-Type': 'text/html; charset=utf-8' } })
  );
  const html = await transformed.text();

  // Save the rendered draft file to R2.
  const destKey = `sandbox/${tenantId}/tours/${tour.slug}.html`;
  await env.TOUR_PAGES.put(destKey, html, {
    httpMetadata:   { contentType: 'text/html; charset=utf-8', cacheControl: 'no-store' },
    customMetadata: {
      tour_id:    tour.id,
      tenant_id:  tenantId,
      status:     'draft',
      created_at: new Date().toISOString(),
    },
  });

  return { ok: true, r2_key: destKey };
}

// ── generateTourPage ──────────────────────────────────────────────────────────
/**
 * Core publishing function.
 * 1. Fetches the HTML template from R2 at templates/{template_id}.html
 * 2. Parses content_data JSON
 * 3. Builds the placeholder map
 * 4. Returns rendered HTML string
 *
 * @param {object} env              - Worker env (env.TOUR_PAGES R2 binding required)
 * @param {object} tour             - DB row from tours (content_data as raw string)
 * @param {string} [templateIdOverride] - Use this template instead of tour.template_id
 * @param {object|null} [paymentConfig] - Parsed payment_config_json for pay-button injection
 * @param {'live'|'preview'} [renderMode='live']
 *   'live'    — clean whitelabel output (no platform branding, pay button active if configured)
 *   'preview' — platform subdomain view (preview banner, pay button disabled, attribution shown)
 * @returns {Promise<{ok: true, html: string} | {ok: false, error: string}>}
 */
export async function generateTourPage(env, tour, templateIdOverride, paymentConfig = null, renderMode = 'live') {
  if (!env.TOUR_PAGES) {
    return { ok: false, error: 'R2 binding TOUR_PAGES is not configured on this Worker.' };
  }

  const tmplId  = safeId(templateIdOverride ?? tour.template_id ?? 'default');
  const tmplKey = `templates/${tmplId}.html`;

  const tmplObj = await env.TOUR_PAGES.get(tmplKey);
  if (!tmplObj) {
    return {
      ok:    false,
      error: `Template not found in R2: "${tmplKey}". Upload it via PUT /api/tours/templates/${tmplId}`,
    };
  }
  const templateHtml = await tmplObj.text();

  // Parse content_data — stored as JSON TEXT in D1
  let content = {};
  if (tour.content_data) {
    try {
      content = typeof tour.content_data === 'string'
        ? JSON.parse(tour.content_data)
        : tour.content_data;
    } catch {
      return { ok: false, error: 'content_data is not valid JSON.' };
    }
  }

  const vars = {
    TOUR_NAME:  content.tour_name  ?? tour.title ?? '',
    TOUR_CODE:  content.tour_code  ?? '',
    ITINERARY:  renderItinerary(content.itinerary  ?? []),
    BASE_PRICE: content.base_price != null ? String(content.base_price) : '',
    DURATION:   tour.duration_text ?? content.duration ?? '',
    HIGHLIGHTS: renderList(content.highlights),
    INCLUDES:   renderList(content.includes),
    EXCLUDES:   renderList(content.excludes),
    TOUR_SLUG:       tour.slug      ?? '',
    TENANT_ID:       tour.tenant_id ?? '',
    LANG:            tour.lang      ?? 'vi',
    // Environment-aware slots — differ between live (whitelabel) and preview (platform subdomain)
    PAY_BUTTON:      renderMode === 'preview'
                       ? buildPreviewPayButton()
                       : (buildPayButton(paymentConfig, tour.slug ?? '') ?? ''),
    PREVIEW_BANNER:  renderMode === 'preview' ? buildPreviewBanner()  : '',
    PLATFORM_BRAND:  renderMode === 'preview' ? buildPlatformBrand() : '',
  };

  return { ok: true, html: applyPlaceholders(templateHtml, vars) };
}

// ── Template management ───────────────────────────────────────────────────────

// PUT /api/tours/templates/:templateId — Upload an HTML template to R2
tours.put('/templates/:templateId', async (c) => {
  const tenantId = c.req.header('X-Tenant-ID')?.trim();
  if (!tenantId) return c.json({ error: 'X-Tenant-ID header is required.' }, 400);

  if (!c.env.TOUR_PAGES) {
    return c.json({ error: 'R2 binding TOUR_PAGES is not configured on this Worker.' }, 503);
  }

  const tmplId = safeId(c.req.param('templateId'));
  if (!tmplId) return c.json({ error: 'Invalid template ID.' }, 400);

  const ct = c.req.header('content-type') ?? '';
  if (!ct.includes('text/html') && !ct.includes('text/plain')) {
    return c.json({ error: 'Content-Type must be text/html or text/plain.' }, 400);
  }

  const body = await c.req.text();
  if (!body.trim()) return c.json({ error: 'Template HTML body is empty.' }, 400);

  const key = `templates/${tmplId}.html`;
  await c.env.TOUR_PAGES.put(key, body, {
    httpMetadata:   { contentType: 'text/html; charset=utf-8' },
    customMetadata: { uploaded_by: tenantId, uploaded_at: new Date().toISOString() },
  });

  return c.json({ ok: true, template_id: tmplId, r2_key: key }, 201);
});

// GET /api/tours/templates/:templateId — Read an HTML template from R2
tours.get('/templates/:templateId', async (c) => {
  const tenantId = c.req.header('X-Tenant-ID')?.trim();
  if (!tenantId) return c.json({ error: 'X-Tenant-ID header is required.' }, 400);

  if (!c.env.TOUR_PAGES) {
    return c.json({ error: 'R2 binding TOUR_PAGES is not configured on this Worker.' }, 503);
  }

  const tmplId = safeId(c.req.param('templateId'));
  const obj    = await c.env.TOUR_PAGES.get(`templates/${tmplId}.html`);
  if (!obj) return c.json({ error: `Template "${tmplId}" not found.` }, 404);

  return new Response(await obj.text(), {
    headers: { 'Content-Type': 'text/html; charset=utf-8' },
  });
});

// ── Tour CRUD ─────────────────────────────────────────────────────────────────

// GET /api/tours — List all tours for a tenant
tours.get('/', async (c) => {
  const tenantId = c.req.header('X-Tenant-ID')?.trim();
  if (!tenantId) return c.json({ error: 'X-Tenant-ID header is required.' }, 400);

  const { results } = await c.env.DB
    .prepare(
      `SELECT id, title, slug, template_id, status, category_id, tour_type,
              published_at, published_url, lang, duration_text, start_date, created_at, content_data
       FROM tours WHERE tenant_id = ? ORDER BY created_at DESC`
    )
    .bind(tenantId)
    .all();

  return c.json({ ok: true, tours: results });
});

// POST /api/tours — Create a tour with optional content_data
tours.post('/', async (c) => {
  const tenantId = c.req.header('X-Tenant-ID')?.trim();
  if (!tenantId) return c.json({ error: 'X-Tenant-ID header is required.' }, 400);

  // Validate tenant exists before any INSERT to avoid FK constraint 500
  const tenant = await c.env.DB
    .prepare('SELECT id FROM tenants WHERE id = ?')
    .bind(tenantId)
    .first();
  if (!tenant) return c.json({ error: `Tenant "${tenantId}" not found. Check your Tenant ID.` }, 404);

  let body;
  try { body = await c.req.json(); }
  catch { return c.json({ error: 'Request body is not valid JSON.' }, 400); }

  if (!body.title) return c.json({ error: 'Missing required field: title.' }, 400);

  const id        = nanoid();
  const now       = Math.floor(Date.now() / 1000);
  const slug      = safeId(slugify(body.slug ?? body.title)) + '-' + id.slice(0, 6);
  const tmplId    = safeId(body.template_id ?? 'default');

  // Serialize content_data — accept object or pre-stringified JSON
  let contentData = null;
  if (body.content_data != null) {
    contentData = typeof body.content_data === 'string'
      ? body.content_data
      : JSON.stringify(body.content_data);
  }

  // Slug uniqueness guard (belt-and-suspenders alongside the DB unique index)
  const clash = await c.env.DB
    .prepare('SELECT id FROM tours WHERE tenant_id = ? AND slug = ?')
    .bind(tenantId, slug)
    .first();
  if (clash) return c.json({ error: `Slug "${slug}" already exists for this tenant.` }, 409);

  await c.env.DB
    .prepare(
      `INSERT INTO tours
         (id, tenant_id, title, lang, duration_text, start_date, status,
          slug, content_data, template_id, tour_type, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    )
    .bind(
      id, tenantId, body.title,
      body.lang          ?? 'vi',
      body.duration_text ?? null,
      body.start_date    ?? null,
      body.status        ?? 'draft',
      slug, contentData, tmplId,
      body.tour_type === 'day_tour' ? 'day_tour' : 'package',
      now
    )
    .run();

  // ── Non-blocking sandbox draft page render ──────────────────────────────
  // Attempt to generate a draft static page from the tenant's sandbox template.
  // Non-fatal: tour creation succeeds even if the sandbox template is absent
  // (initializeTenantSandbox has not been called yet for this tenant).
  let draftPage = null;
  try {
    draftPage = await renderAndSaveDraftPage(c.env, tenantId, {
      id,
      slug,
      title: body.title,
      content_data:  contentData,
      duration_text: body.duration_text ?? null,
    });
  } catch (err) {
    // Never block tour creation for a draft-render error — log and continue.
    console.warn(`[DRAFT_RENDER_WARN] tour=${id} tenant=${tenantId}`, err?.message);
  }

  scheduleUniversalTourSync(c, tenantId, id);

  return c.json({
    ok:          true,
    id,
    slug,
    template_id: tmplId,
    status:      'draft',
    ...(draftPage?.ok
      ? { draft_page_key: draftPage.r2_key }
      : { draft_page_note: draftPage?.reason ?? 'Draft page not generated.' }),
  }, 201);
});

// GET /api/tours/:id — Read a single tour (content_data auto-parsed)
tours.get('/:id', async (c) => {
  const tenantId = c.req.header('X-Tenant-ID')?.trim();
  if (!tenantId) return c.json({ error: 'X-Tenant-ID header is required.' }, 400);

  const tour = await c.env.DB
    .prepare('SELECT * FROM tours WHERE id = ? AND tenant_id = ?')
    .bind(c.req.param('id'), tenantId)
    .first();
  if (!tour) return c.json({ error: 'Tour not found.' }, 404);

  // Return content_data as a parsed object for convenience
  if (tour.content_data) {
    try { tour.content_data = JSON.parse(tour.content_data); } catch { /* keep raw */ }
  }
  return c.json({ ok: true, tour });
});

// PATCH /api/tours/:id — Update metadata and/or content_data
tours.patch('/:id', async (c) => {
  const tenantId = c.req.header('X-Tenant-ID')?.trim();
  if (!tenantId) return c.json({ error: 'X-Tenant-ID header is required.' }, 400);

  let body;
  try { body = await c.req.json(); }
  catch { return c.json({ error: 'Request body is not valid JSON.' }, 400); }

  // Whitelist prevents column-injection; tenant_id / id / created_at are immutable
  const ALLOWED = ['title', 'lang', 'duration_text', 'start_date', 'status', 'content_data', 'template_id', 'slug', 'category_id', 'tour_type', 'meta_title', 'meta_description', 'og_image'];
  const updates  = {};
  for (const key of ALLOWED) {
    if (!(key in body)) continue;
    if (key === 'content_data') {
      updates.content_data = typeof body.content_data === 'string'
        ? body.content_data
        : JSON.stringify(body.content_data);
    } else if (key === 'template_id') {
      updates.template_id = safeId(body.template_id);
    } else if (key === 'slug') {
      updates.slug = safeId(slugify(body.slug));
    } else if (key === 'category_id') {
      // Accept null (clear assignment) or a non-empty string
      if (body.category_id === null) {
        updates.category_id = null;
      } else if (typeof body.category_id === 'string' && body.category_id.trim()) {
        // [SEC] Verify category belongs to this tenant before assigning
        const cat = await c.env.DB
          .prepare('SELECT id FROM tour_categories WHERE id = ? AND tenant_id = ?')
          .bind(body.category_id.trim(), tenantId)
          .first();
        if (!cat) return c.json({ error: 'category_id not found for this tenant.' }, 404);
        updates.category_id = body.category_id.trim();
      }
    } else {
      updates[key] = body[key];
    }
  }

  if (Object.keys(updates).length === 0) {
    return c.json({ error: 'No updatable fields provided.' }, 400);
  }

  const setClauses = Object.keys(updates).map(k => `${k} = ?`).join(', ');
  const values     = [...Object.values(updates), c.req.param('id'), tenantId];

  const result = await c.env.DB
    .prepare(`UPDATE tours SET ${setClauses} WHERE id = ? AND tenant_id = ?`)
    .bind(...values)
    .run();

  if (result.meta.changes === 0) return c.json({ error: 'Tour not found.' }, 404);
  scheduleUniversalTourSync(c, tenantId, c.req.param('id'));
  return c.json({ ok: true, updated: Object.keys(updates) });
});

// ── Publishing endpoints ──────────────────────────────────────────────────────

// GET /api/tours/:id/preview
// Re-renders the tour ON THE FLY in 'preview' mode — always shows the
// preview banner + disabled pay button. Serves both draft and published tours.
// [IMPORTANT] Does NOT serve from R2 cache — so agents can preview even before
// publishing, and the preview is never confused with the live whitelabel page.
tours.get('/:id/preview', async (c) => {
  const tenantId = c.req.header('X-Tenant-ID')?.trim();
  if (!tenantId) return c.json({ error: 'X-Tenant-ID header is required.' }, 400);
  if (!c.env.TOUR_PAGES) return c.json({ error: 'R2 binding TOUR_PAGES is not configured.' }, 503);

  // Fetch full row — preview works for draft (no slug) and published tours alike
  const tour = await c.env.DB
    .prepare('SELECT * FROM tours WHERE id = ? AND tenant_id = ?')
    .bind(c.req.param('id'), tenantId)
    .first();
  if (!tour) return c.json({ error: 'Tour not found.' }, 404);

  // No subscription gate for preview — render with no payment config, preview mode
  const rendered = await generateTourPage(c.env, tour, undefined, null, 'preview');
  if (!rendered.ok) return c.json({ error: rendered.error }, 422);

  return new Response(rendered.html, {
    headers: {
      'Content-Type':  'text/html; charset=utf-8',
      'X-Render-Mode': 'preview',
      'Cache-Control': 'no-store, no-cache',
    },
  });
});

// POST /api/tours/:id/publish — Render HTML from template + content_data, save to R2
tours.post('/:id/publish', async (c) => {
  const tenantId = c.req.header('X-Tenant-ID')?.trim();
  if (!tenantId) return c.json({ error: 'X-Tenant-ID header is required.' }, 400);
  if (!c.env.TOUR_PAGES) return c.json({ error: 'R2 binding TOUR_PAGES is not configured.' }, 503);

  // Showcase publish guard
  const guard = await checkPublishPermission(c.env, tenantId);
  if (!guard.ok) return c.json({ error: guard.error, code: guard.code, blocks: guard.blocks, checklist: guard.checklist }, 403);

  const tour = await c.env.DB
    .prepare('SELECT * FROM tours WHERE id = ? AND tenant_id = ?')
    .bind(c.req.param('id'), tenantId)
    .first();
  if (!tour)      return c.json({ error: 'Tour not found.' }, 404);
  if (!tour.slug) return c.json({ error: 'Tour must have a slug before publishing. Use PATCH /api/tours/:id to set one.' }, 422);

  const rendered = await generateTourPage(c.env, tour, undefined, guard.paymentConfig, 'live');
  if (!rendered.ok) return c.json({ error: rendered.error }, 422);

  // /{tenant_id}/{tour_slug}.html — the canonical published path
  const r2Key = `${tenantId}/${tour.slug}.html`;
  await c.env.TOUR_PAGES.put(r2Key, rendered.html, {
    httpMetadata:   { contentType: 'text/html; charset=utf-8' },
    customMetadata: {
      tour_id:      tour.id,
      tenant_id:    tenantId,
      template_id:  tour.template_id ?? 'default',
      published_at: new Date().toISOString(),
    },
  });

  const now = Math.floor(Date.now() / 1000);
  await c.env.DB
    .prepare('UPDATE tours SET published_at = ?, published_url = ?, status = ? WHERE id = ? AND tenant_id = ?')
    .bind(now, r2Key, 'on_sale', tour.id, tenantId)
    .run();

  return c.json({
    ok:           true,
    tour_id:      tour.id,
    slug:         tour.slug,
    r2_key:       r2Key,
    template_id:  tour.template_id ?? 'default',
    published_at: new Date(now * 1000).toISOString(),
  });
});

// POST /api/tours/:id/switch-template — Swap template, re-render, preserve published URL
tours.post('/:id/switch-template', async (c) => {
  const tenantId = c.req.header('X-Tenant-ID')?.trim();
  if (!tenantId) return c.json({ error: 'X-Tenant-ID header is required.' }, 400);
  if (!c.env.TOUR_PAGES) return c.json({ error: 'R2 binding TOUR_PAGES is not configured.' }, 503);

  // Showcase publish guard — template swap re-renders the page so it needs the same gate
  const guard = await checkPublishPermission(c.env, tenantId);
  if (!guard.ok) return c.json({ error: guard.error, code: guard.code, blocks: guard.blocks, checklist: guard.checklist }, 403);

  let body;
  try { body = await c.req.json(); }
  catch { return c.json({ error: 'Request body is not valid JSON.' }, 400); }

  const newTemplateId = safeId(body.template_id ?? '');
  if (!newTemplateId) return c.json({ error: 'Missing required field: template_id.' }, 400);

  // Validate template exists BEFORE making any DB changes
  const tmplObj = await c.env.TOUR_PAGES.get(`templates/${newTemplateId}.html`);
  if (!tmplObj) {
    return c.json({
      error: `Template "${newTemplateId}" not found in R2. Upload it first via PUT /api/tours/templates/${newTemplateId}`,
    }, 404);
  }

  const tour = await c.env.DB
    .prepare('SELECT * FROM tours WHERE id = ? AND tenant_id = ?')
    .bind(c.req.param('id'), tenantId)
    .first();
  if (!tour)      return c.json({ error: 'Tour not found.' }, 404);
  if (!tour.slug) return c.json({ error: 'Tour must have a slug. Use PATCH /api/tours/:id to set one.' }, 422);

  // Re-render with the new template — content_data is unchanged
  const rendered = await generateTourPage(c.env, tour, newTemplateId, guard.paymentConfig, 'live');
  if (!rendered.ok) return c.json({ error: rendered.error }, 422);

  // Write to the SAME R2 key — the published URL is preserved
  const r2Key = `${tenantId}/${tour.slug}.html`;
  await c.env.TOUR_PAGES.put(r2Key, rendered.html, {
    httpMetadata:   { contentType: 'text/html; charset=utf-8' },
    customMetadata: {
      tour_id:      tour.id,
      tenant_id:    tenantId,
      template_id:  newTemplateId,
      published_at: new Date().toISOString(),
    },
  });

  const now = Math.floor(Date.now() / 1000);
  await c.env.DB
    .prepare('UPDATE tours SET template_id = ?, published_at = ?, published_url = ? WHERE id = ? AND tenant_id = ?')
    .bind(newTemplateId, now, r2Key, tour.id, tenantId)
    .run();

  return c.json({
    ok:              true,
    tour_id:         tour.id,
    slug:            tour.slug,
    r2_key:          r2Key,
    old_template_id: tour.template_id ?? 'default',
    new_template_id: newTemplateId,
    published_at:    new Date(now * 1000).toISOString(),
    note:            'Published URL unchanged. content_data preserved.',
  });
});

// DELETE /api/tours/:id — Hard-delete a tour and all child rows for this tenant.
// Cascade order:  tour_prices → tour_stops → tours  (FK-safe, all scoped by tenant_id)
// R2 published page is deleted best-effort (non-blocking; failure does not 500).
tours.delete('/:id', async (c) => {
  const tenantId = c.req.header('X-Tenant-ID')?.trim();
  if (!tenantId) return c.json({ error: 'X-Tenant-ID header is required.' }, 400);

  const tourId = c.req.param('id');

  // Confirm ownership before touching anything
  const tour = await c.env.DB
    .prepare('SELECT id, slug, published_url FROM tours WHERE id = ? AND tenant_id = ?')
    .bind(tourId, tenantId)
    .first();
  if (!tour) return c.json({ error: 'Tour not found.' }, 404);

  // Atomic cascade delete via D1 batch
  await c.env.DB.batch([
    c.env.DB.prepare('DELETE FROM tour_prices WHERE tour_id = ? AND tenant_id = ?').bind(tourId, tenantId),
    c.env.DB.prepare('DELETE FROM tour_stops  WHERE tour_id = ? AND tenant_id = ?').bind(tourId, tenantId),
    c.env.DB.prepare('DELETE FROM tours        WHERE id      = ? AND tenant_id = ?').bind(tourId, tenantId),
  ]);

  // Best-effort R2 cleanup — non-blocking
  if (c.env.TOUR_PAGES && tour.published_url) {
    c.env.TOUR_PAGES.delete(tour.published_url).catch(() => {});
  }

  return c.json({ ok: true, deleted: tourId });
});

// POST /api/tours/:id/copy — Deep-clone a tour for this tenant.
// Creates:  new tour row (draft, new id+slug, clears published_*)
//           new tour_stops rows (new IDs, same content)
//           new tour_prices rows (new IDs, pointing at new tour_id)
tours.post('/:id/copy', async (c) => {
  const tenantId = c.req.header('X-Tenant-ID')?.trim();
  if (!tenantId) return c.json({ error: 'X-Tenant-ID header is required.' }, 400);

  const sourceId = c.req.param('id');

  // Confirm source ownership
  const source = await c.env.DB
    .prepare('SELECT * FROM tours WHERE id = ? AND tenant_id = ?')
    .bind(sourceId, tenantId)
    .first();
  if (!source) return c.json({ error: 'Tour not found.' }, 404);

  let body = {};
  try { body = await c.req.json(); } catch { /* title override is optional */ }

  const newId    = nanoid();
  const now      = Math.floor(Date.now() / 1000);
  const newTitle = (body.title?.trim()) || `${source.title} (copy)`;
  const newSlug  = safeId(slugify(newTitle)) + '-' + newId.slice(0, 6);

  // --- Fetch child rows ---
  const [{ results: sourceStops }, { results: sourcePrices }] = await c.env.DB.batch([
    c.env.DB.prepare('SELECT * FROM tour_stops  WHERE tour_id = ? AND tenant_id = ?').bind(sourceId, tenantId),
    c.env.DB.prepare('SELECT * FROM tour_prices WHERE tour_id = ? AND tenant_id = ?').bind(sourceId, tenantId),
  ]);

  // --- Build INSERT statements ---
  const stmtTour = c.env.DB.prepare(
    `INSERT INTO tours
       (id, tenant_id, title, lang, duration_text, start_date, status,
        slug, content_data, template_id, category_id, tour_type, created_at)
     VALUES (?, ?, ?, ?, ?, ?, 'draft', ?, ?, ?, ?, ?, ?)`
  ).bind(
    newId, tenantId, newTitle,
    source.lang          ?? 'vi',
    source.duration_text ?? null,
    source.start_date    ?? null,
    newSlug,
    source.content_data  ?? null,
    source.template_id   ?? 'default',
    source.category_id   ?? null,
    source.tour_type     ?? 'package',
    now
  );

  const stmtStops = sourceStops.map(s => c.env.DB.prepare(
    `INSERT INTO tour_stops
       (id, tenant_id, tour_id, label, day_from, day_to, nights,
        meal_breakfast, meal_lunch, meal_dinner, description,
        services_config, sort_order, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).bind(
    nanoid(), tenantId, newId,
    s.label,
    s.day_from        ?? 1,
    s.day_to          ?? 1,
    s.nights          ?? 0,
    s.meal_breakfast  ?? 0,
    s.meal_lunch      ?? 0,
    s.meal_dinner     ?? 0,
    s.description     ?? null,
    s.services_config ?? null,
    s.sort_order      ?? 0,
    now
  ));

  const stmtPrices = sourcePrices.map(p => c.env.DB.prepare(
    `INSERT INTO tour_prices
       (id, tenant_id, tour_id, season_id, segment_id, pax_band_id,
        base_currency, adult_shared_room_price, adult_single_room_price,
        child_shared_with_parents_price, infant_price, notes, is_active, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).bind(
    nanoid(), tenantId, newId,
    p.season_id,
    p.segment_id,
    p.pax_band_id,
    p.base_currency                   ?? 'USD',
    p.adult_shared_room_price         ?? null,
    p.adult_single_room_price         ?? null,
    p.child_shared_with_parents_price ?? null,
    p.infant_price                    ?? 0,
    p.notes                           ?? null,
    p.is_active                       ?? 1,
    now
  ));

  // Atomic batch — all or nothing
  await c.env.DB.batch([stmtTour, ...stmtStops, ...stmtPrices]);

  scheduleUniversalTourSync(c, tenantId, newId);

  return c.json({
    ok:             true,
    id:             newId,
    title:          newTitle,
    slug:           newSlug,
    status:         'draft',
    copied_stops:   stmtStops.length,
    copied_prices:  stmtPrices.length,
  }, 201);
});

